   CAST(l.FECHA_DESDE_SERV AS datetime) AS [FECHA_DESDE_SERV],
   CAST(l.FECHA_HASTA_SERV AS datetime) AS [FECHA_HASTA_SERV],
   CAST(l.DESC_FORMA_PAGO AS varchar(300)) COLLATE DATABASE_DEFAULT AS [DESC_FORMA_PAGO],
   CAST(l.ID_PROYECTO_VIATICOS AS int) AS [ID],
