   CAST(c.ID AS int) AS [ID_CONSULTOR],
   CAST(CONCAT(CAST('LK_PROYECTO_VIATICOS - valores originales: ' AS varchar(max)),'; ID_PROYECTO_VIATICOS=',COALESCE(CONVERT(varchar(max),l.[ID_PROYECTO_VIATICOS]),'<NULL>'),'; ID_PROYECTO=',COALESCE(CONVERT(varchar(max),l.[ID_PROYECTO]),'<NULL>'),'; ID_TIPO_SERVICIO=',COALESCE(CONVERT(varchar(max),l.[ID_TIPO_SERVICIO]),'<NULL>'),'; ID_AGENDA=',COALESCE(CONVERT(varchar(max),l.[ID_AGENDA]),'<NULL>'),'; TIPO_CONSULTOR=',COALESCE(CONVERT(varchar(max),l.[TIPO_CONSULTOR]),'<NULL>'),'; ID_CONSULTOR=',COALESCE(CONVERT(varchar(max),l.[ID_CONSULTOR]),'<NULL>'),'; ID_PROVEEDOR=',COALESCE(CONVERT(varchar(max),l.[ID_PROVEEDOR]),'<NULL>'),'; TIPO_PROVEEDOR=',COALESCE(CONVERT(varchar(max),l.[TIPO_PROVEEDOR]),'<NULL>'),'; NRO_FC=',COALESCE(CONVERT(varchar(max),l.[NRO_FC]),'<NULL>'),'; CANT_PERSONAS=',COALESCE(CONVERT(varchar(max),l.[CANT_PERSONAS]),'<NULL>'),'; DESCRIP_SERVICIO=',COALESCE(CONVERT(varchar(max),l.[DESCRIP_SERVICIO]),'<NULL>'),'; FECHA_FC=',COALESCE(CONVERT(varchar(max),l.[FECHA_FC],126),'<NULL>'),'; PRECIO_FINAL=',COALESCE(CONVERT(varchar(max),l.[PRECIO_FINAL]),'<NULL>'),'; FORMA_PAGO=',COALESCE(CONVERT(varchar(max),l.[FORMA_PAGO]),'<NULL>'),'; CANT_CUOTAS=',COALESCE(CONVERT(varchar(max),l.[CANT_CUOTAS]),'<NULL>'),'; ESTADO_PAGO=',COALESCE(CONVERT(varchar(max),l.[ESTADO_PAGO]),'<NULL>'),'; FECHA_ULT_PAGO=',COALESCE(CONVERT(varchar(max),l.[FECHA_ULT_PAGO],126),'<NULL>'),'; PRECIO_CUOTA=',COALESCE(CONVERT(varchar(max),l.[PRECIO_CUOTA]),'<NULL>'),'; PROX_VENCIMIENTO=',COALESCE(CONVERT(varchar(max),l.[PROX_VENCIMIENTO],126),'<NULL>'),'; SALDO_PEND=',COALESCE(CONVERT(varchar(max),l.[SALDO_PEND]),'<NULL>'),'; DESTINO=',COALESCE(CONVERT(varchar(max),l.[DESTINO]),'<NULL>'),'; FECHA_DESDE_SERV=',COALESCE(CONVERT(varchar(max),l.[FECHA_DESDE_SERV],126),'<NULL>'),'; FECHA_HASTA_SERV=',COALESCE(CONVERT(varchar(max),l.[FECHA_HASTA_SERV],126),'<NULL>'),'; DESC_FORMA_PAGO=',COALESCE(CONVERT(varchar(max),l.[DESC_FORMA_PAGO]),'<NULL>')) AS varchar(max)) COLLATE DATABASE_DEFAULT AS [OBSERVACIONES],
