  CREATE UNIQUE CLUSTERED INDEX IX_W_ID ON #W([ID]);
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS',[ID],'REFERENCIAS',CONCAT(CAST(N'Referencia inexistente/ambigua; fila conservada con FK NULL: ' AS nvarchar(max)),OBSERVACIONES) FROM #W WHERE ID_PROYECTO IS NULL OR (ID_AGENDA IS NOT NULL AND ID_VISITA IS NULL) OR (NULLIF(LTRIM(RTRIM(ID_CONSULTOR_ORIGEN)),'') IS NOT NULL AND ID_CONSULTOR IS NULL);
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS',[ID],'ID_PROVEEDOR',CONCAT(CAST(N'Proveedor inexistente; FK NULL: ' AS nvarchar(max)),OBSERVACIONES) FROM #W WHERE ID_PROVEEDOR_ORIGEN IS NOT NULL AND ID_PROVEEDOR IS NULL;
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS',[ID],'TIPO_PROVEEDOR',CONCAT(CAST(N'Tipo de viatico desconocido; texto conservado: ' AS nvarchar(max)),OBSERVACIONES) FROM #W WHERE ISNULL(UPPER(LTRIM(RTRIM(TIPO_PROVEEDOR))),'') NOT IN ('MICRO','HOTEL','REMIS','AVION','REFRIGERIO','TAXI','ALQUILER','AUTO');
  CREATE TABLE #WD([ID_AGENDA] int NULL,[DET_PROV_RESERVA] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_VUELO] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_ORIGEN] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_DESTINO] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_SALIDA] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_LLEGADA] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_LOCAL] varchar(max) COLLATE DATABASE_DEFAULT NULL,[PAGA_CONSULTOR] varchar(max) COLLATE DATABASE_DEFAULT NULL,[PAGA_CONSULTORA] varchar(max) COLLATE DATABASE_DEFAULT NULL,[RENDICION_CLIENTE] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_KMS] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_PEAJES] varchar(max) COLLATE DATABASE_DEFAULT NULL,[DET_PROV_FECHA] datetime NULL,[DET_PROV_FINGRESO] datetime NULL,[DET_PROV_FEGRESO] datetime NULL,[DET_PROV_FPARTIDA] datetime NULL,[DET_PROV_FLLEGADA] datetime NULL,[ID] int NULL,[ID_VIATICO] int NULL,[ID_VISITA] int NULL,[ID_PROYECTO_VIATICOS_ORIGEN] int NULL,[KMS_NUMERICO] numeric(15,2) NULL,[PEAJES_NUMERICO] numeric(15,2) NULL,[OBSERVACIONES] varchar(max) COLLATE DATABASE_DEFAULT NULL);
  IF OBJECT_ID(N'dbo.LK_PROYECTO_VIATICOS_DET',N'U') IS NOT NULL EXEC sys.sp_executesql N'INSERT #WD([ID_AGENDA],[DET_PROV_RESERVA],[DET_PROV_VUELO],[DET_PROV_ORIGEN],[DET_PROV_DESTINO],[DET_PROV_SALIDA],[DET_PROV_LLEGADA],[DET_PROV_LOCAL],[PAGA_CONSULTOR],[PAGA_CONSULTORA],[RENDICION_CLIENTE],[DET_PROV_KMS],[DET_PROV_PEAJES],[DET_PROV_FECHA],[DET_PROV_FINGRESO],[DET_PROV_FEGRESO],[DET_PROV_FPARTIDA],[DET_PROV_FLLEGADA],[ID],[ID_VIATICO],[ID_VISITA],[ID_PROYECTO_VIATICOS_ORIGEN],[KMS_NUMERICO],[PEAJES_NUMERICO],[OBSERVACIONES]) SELECT CAST(l.ID_AGENDA AS int),CAST(l.DET_PROV_RESERVA AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_VUELO AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_ORIGEN AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_DESTINO AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_SALIDA AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_LLEGADA AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_LOCAL AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.PAGA_CONSULTOR AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.PAGA_CONSULTORA AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.RENDICION_CLIENTE AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_KMS AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_PEAJES AS varchar(max)) COLLATE DATABASE_DEFAULT,CAST(l.DET_PROV_FECHA AS datetime),CAST(l.DET_PROV_FINGRESO AS datetime),CAST(l.DET_PROV_FEGRESO AS datetime),CAST(l.DET_PROV_FPARTIDA AS datetime),CAST(l.DET_PROV_FLLEGADA AS datetime),CAST(l.ID_PROYECTO_VIATICOS_DET AS int),CAST(w.ID AS int),CAST(v.ID AS int),CAST(l.ID_PROYECTO_VIATICOS AS int),CAST(dbo.VCT_MIG_PROY_IMPORTE(l.DET_PROV_KMS) AS numeric(15,2)),CAST(dbo.VCT_MIG_PROY_IMPORTE(l.DET_PROV_PEAJES) AS numeric(15,2)),CAST(CONCAT(CAST(''LK_PROYECTO_VIATICOS_DET - valores originales: '' AS varchar(max)),''; ID_PROYECTO_VIATICOS_DET='',COALESCE(CONVERT(varchar(max),l.[ID_PROYECTO_VIATICOS_DET]),''<NULL>''),''; ID_PROYECTO_VIATICOS='',COALESCE(CONVERT(varchar(max),l.[ID_PROYECTO_VIATICOS]),''<NULL>''),''; ID_AGENDA='',COALESCE(CONVERT(varchar(max),l.[ID_AGENDA]),''<NULL>''),''; DET_PROV_RESERVA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_RESERVA]),''<NULL>''),''; DET_PROV_VUELO='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_VUELO]),''<NULL>''),''; DET_PROV_ORIGEN='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_ORIGEN]),''<NULL>''),''; DET_PROV_DESTINO='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_DESTINO]),''<NULL>''),''; DET_PROV_SALIDA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_SALIDA]),''<NULL>''),''; DET_PROV_LLEGADA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_LLEGADA]),''<NULL>''),''; DET_PROV_LOCAL='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_LOCAL]),''<NULL>''),''; PAGA_CONSULTOR='',COALESCE(CONVERT(varchar(max),l.[PAGA_CONSULTOR]),''<NULL>''),''; PAGA_CONSULTORA='',COALESCE(CONVERT(varchar(max),l.[PAGA_CONSULTORA]),''<NULL>''),''; RENDICION_CLIENTE='',COALESCE(CONVERT(varchar(max),l.[RENDICION_CLIENTE]),''<NULL>''),''; DET_PROV_KMS='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_KMS]),''<NULL>''),''; DET_PROV_PEAJES='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_PEAJES]),''<NULL>''),''; DET_PROV_FECHA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_FECHA],126),''<NULL>''),''; DET_PROV_FINGRESO='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_FINGRESO],126),''<NULL>''),''; DET_PROV_FEGRESO='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_FEGRESO],126),''<NULL>''),''; DET_PROV_FPARTIDA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_FPARTIDA],126),''<NULL>''),''; DET_PROV_FLLEGADA='',COALESCE(CONVERT(varchar(max),l.[DET_PROV_FLLEGADA],126),''<NULL>'')) AS varchar(max)) COLLATE DATABASE_DEFAULT FROM dbo.LK_PROYECTO_VIATICOS_DET l WITH(HOLDLOCK) LEFT JOIN #W w ON w.ID=l.ID_PROYECTO_VIATICOS LEFT JOIN #V v ON v.ID=l.ID_AGENDA;';
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS_DET',[ID],'REFERENCIAS',CONCAT(CAST(N'Detalle conservado con FK NULL por referencia faltante: ' AS nvarchar(max)),OBSERVACIONES) FROM #WD WHERE ID_VIATICO IS NULL OR (ID_AGENDA IS NOT NULL AND ID_VISITA IS NULL);
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS_DET',[ID],'DET_PROV_KMS',CONCAT(CAST(N'Valor numerico ambiguo; texto conservado: ' AS nvarchar(max)),OBSERVACIONES) FROM #WD WHERE NULLIF(LTRIM(RTRIM(DET_PROV_KMS)),'') IS NOT NULL AND KMS_NUMERICO IS NULL;
  INSERT #Excepciones SELECT 'LK_PROYECTO_VIATICOS_DET',[ID],'DET_PROV_PEAJES',CONCAT(CAST(N'Valor numerico ambiguo; texto conservado: ' AS nvarchar(max)),OBSERVACIONES) FROM #WD WHERE NULLIF(LTRIM(RTRIM(DET_PROV_PEAJES)),'') IS NOT NULL AND PEAJES_NUMERICO IS NULL;
  CREATE INDEX IX_EX_ORIGEN ON #Excepciones(TABLA_ORIGEN,ID_ORIGEN) INCLUDE(CAMPO);
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #P p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #S p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO_SERVICIO' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #V p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_AGENDA' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #F p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO_HONORARIOS' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #W p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO_VIATICOS' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #WD p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO_VIATICOS_DET' AND e.ID_ORIGEN=p.ID ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE p SET OBSERVACIONES=CONCAT(p.OBSERVACIONES,CHAR(13),CHAR(10),x.NOTAS) FROM #R p CROSS APPLY(SELECT (SELECT CHAR(13)+CHAR(10)+'EXCEPCION '+e.CAMPO+' (detalle completo en VCT_MIGRACION_PROYECTOS_EXCEPCIONES).' FROM #Excepciones e WHERE e.TABLA_ORIGEN='LK_PROYECTO_RENTABILIDAD' AND e.ID_ORIGEN=p.ID_PROYECTO_RENTA ORDER BY e.CAMPO FOR XML PATH(''),TYPE).value('.','varchar(max)') NOTAS) x;
  UPDATE #D SET OBSERVACIONES=CONCAT(OBSERVACIONES,CASE WHEN TIPO_ENTIDAD='DESCONOCIDO' THEN CHAR(13)+CHAR(10)+'EXCEPCION: persona inexistente.' ELSE '' END,CASE WHEN UPPER(LTRIM(RTRIM(TIPO)))='A' AND ID_VISITA IS NULL THEN CHAR(13)+CHAR(10)+'EXCEPCION: visita inexistente.' ELSE '' END,CASE WHEN ISNULL(UPPER(LTRIM(RTRIM(TIPO))),'') NOT IN ('OC','ND','D','OP','OA','A','LIC','POT') THEN CHAR(13)+CHAR(10)+'EXCEPCION: tipo de disponibilidad desconocido.' ELSE '' END);
  CREATE TABLE #Resumen(Tabla sysname COLLATE DATABASE_DEFAULT PRIMARY KEY,Temp sysname COLLATE DATABASE_DEFAULT,Esperadas bigint,ColumnaId sysname COLLATE DATABASE_DEFAULT);
  INSERT #Resumen VALUES('VCT_PROYECTOS','P',(SELECT COUNT_BIG(*) FROM #P),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_SERVICIOS','S',(SELECT COUNT_BIG(*) FROM #S),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_VISITAS','V',(SELECT COUNT_BIG(*) FROM #V),'ID');
  INSERT #Resumen VALUES('VCT_AGENDA_PERSONAS','D',(SELECT COUNT_BIG(*) FROM #D),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_VISITAS_CONSULTORES','VC_ID',(SELECT COUNT_BIG(*) FROM #VC_ID),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_EQUIPO','E',(SELECT COUNT_BIG(*) FROM #E),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_NORMAS','PN',(SELECT COUNT_BIG(*) FROM #PN),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_VISITAS_NORMAS','VN',(SELECT COUNT_BIG(*) FROM #VN),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_RENTABILIDAD','R',(SELECT COUNT_BIG(*) FROM #R),'ID_PROYECTO_RENTA');
  INSERT #Resumen VALUES('VCT_PROYECTOS_HONORARIOS','F',(SELECT COUNT_BIG(*) FROM #F),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_VIATICOS','W',(SELECT COUNT_BIG(*) FROM #W),'ID');
  INSERT #Resumen VALUES('VCT_PROYECTOS_VIATICOS_DET','WD',(SELECT COUNT_BIG(*) FROM #WD),'ID');
  SELECT Tabla,Esperadas FROM #Resumen ORDER BY Tabla;
  SELECT TABLA_ORIGEN,CAMPO,COUNT_BIG(*) Cantidad FROM #Excepciones GROUP BY TABLA_ORIGEN,CAMPO ORDER BY TABLA_ORIGEN,CAMPO;
  SELECT SUM(CONVERT(bigint,TOTAL_HORAS_EJECUTADAS)) HORAS_EJECUTADAS,SUM(CONVERT(bigint,HORAS_SIN_CONSULTOR)) HORAS_SIN_CONSULTOR FROM #V;
  IF @Aplicar=0
  BEGIN
   SELECT * FROM #Excepciones ORDER BY TABLA_ORIGEN,ID_ORIGEN,CAMPO;
   ROLLBACK TRANSACTION;
   RETURN;
  END;
  DECLARE @Tablas TABLE(ObjectId int PRIMARY KEY,Nombre sysname);
  INSERT @Tablas SELECT OBJECT_ID(N'dbo.'+Tabla),Tabla FROM #Resumen;
  IF EXISTS(SELECT 1 FROM #Resumen r LEFT JOIN sys.identity_columns c ON c.object_id=OBJECT_ID(N'dbo.'+r.Tabla)
    WHERE c.column_id IS NULL OR c.name COLLATE DATABASE_DEFAULT<>r.ColumnaId COLLATE DATABASE_DEFAULT OR CONVERT(bigint,c.seed_value)<>1 OR CONVERT(bigint,c.increment_value)<>1)
   THROW 55009,'Identidades diferentes del modelo suministrado.',1;
  DECLARE bloquear CURSOR LOCAL FAST_FORWARD FOR SELECT Nombre FROM @Tablas ORDER BY ObjectId;
  OPEN bloquear; FETCH NEXT FROM bloquear INTO @nombre;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @sql=N'SELECT @N=COUNT_BIG(*) FROM dbo.'+QUOTENAME(@nombre)+N' WITH(TABLOCKX,HOLDLOCK);';
   EXEC sys.sp_executesql @sql,N'@N bigint OUTPUT',@N=@n OUTPUT;
   FETCH NEXT FROM bloquear INTO @nombre;
  END;
  CLOSE bloquear; DEALLOCATE bloquear;
  -- Evitar reasignar IDs regenerados que tengan referencias externas (incluye documentos/planes).
  DECLARE dependencias CURSOR LOCAL FAST_FORWARD FOR
   SELECT f.parent_object_id,f.name,
    N'SELECT @H=CASE WHEN EXISTS(SELECT 1 FROM '+QUOTENAME(OBJECT_SCHEMA_NAME(f.parent_object_id))+N'.'+QUOTENAME(OBJECT_NAME(f.parent_object_id))+N' d WITH(HOLDLOCK) WHERE '
    +STUFF((SELECT N' AND d.'+QUOTENAME(COL_NAME(fc.parent_object_id,fc.parent_column_id))+N' IS NOT NULL' FROM sys.foreign_key_columns fc WHERE fc.constraint_object_id=f.object_id ORDER BY fc.constraint_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)'),1,5,N'')+N') THEN 1 ELSE 0 END;'
   FROM sys.foreign_keys f JOIN @Tablas t ON t.ObjectId=f.referenced_object_id
   WHERE t.Nombre IN ('VCT_PROYECTOS_EQUIPO','VCT_PROYECTOS_NORMAS','VCT_PROYECTOS_VISITAS_CONSULTORES','VCT_PROYECTOS_VISITAS_NORMAS','VCT_AGENDA_PERSONAS')
    AND NOT EXISTS(SELECT 1 FROM @Tablas x WHERE x.ObjectId=f.parent_object_id);
  OPEN dependencias; FETCH NEXT FROM dependencias INTO @parent,@nombre,@sql;
  WHILE @@FETCH_STATUS=0
  BEGIN
   EXEC sys.sp_executesql @sql,N'@H bit OUTPUT',@H=@hay OUTPUT;
   IF @hay=1
   BEGIN
    SELECT OBJECT_SCHEMA_NAME(@parent) Esquema,OBJECT_NAME(@parent) TablaExterna,@nombre Restriccion;
    THROW 55010,'Hay referencias externas a IDs regenerados; no se borraron documentos/planes. Resolver esa dependencia.',1;
   END;
   FETCH NEXT FROM dependencias INTO @parent,@nombre,@sql;
  END;
  CLOSE dependencias; DEALLOCATE dependencias;
  CREATE TABLE #FKs(ParentId int,Nombre sysname COLLATE DATABASE_DEFAULT,Deshabilitada bit,NoConfiable bit);
  INSERT #FKs SELECT f.parent_object_id,f.name,f.is_disabled,f.is_not_trusted FROM sys.foreign_keys f
   WHERE EXISTS(SELECT 1 FROM @Tablas t WHERE t.ObjectId=f.parent_object_id OR t.ObjectId=f.referenced_object_id);
  CREATE TABLE #Triggers(ParentId int,Nombre sysname COLLATE DATABASE_DEFAULT);
  INSERT #Triggers SELECT tr.parent_id,tr.name FROM sys.triggers tr JOIN @Tablas t ON t.ObjectId=tr.parent_id WHERE tr.is_disabled=0;
  DECLARE desactivar CURSOR LOCAL FAST_FORWARD FOR SELECT ParentId,Nombre FROM #FKs WHERE Deshabilitada=0;
  OPEN desactivar; FETCH NEXT FROM desactivar INTO @parent,@nombre;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @sql=N'ALTER TABLE '+QUOTENAME(OBJECT_SCHEMA_NAME(@parent))+N'.'+QUOTENAME(OBJECT_NAME(@parent))+N' NOCHECK CONSTRAINT '+QUOTENAME(@nombre)+N';'; EXEC sys.sp_executesql @sql;
   FETCH NEXT FROM desactivar INTO @parent,@nombre;
  END;
  CLOSE desactivar; DEALLOCATE desactivar;
  DECLARE desactivartrg CURSOR LOCAL FAST_FORWARD FOR SELECT ParentId,Nombre FROM #Triggers;
  OPEN desactivartrg; FETCH NEXT FROM desactivartrg INTO @parent,@nombre;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @sql=N'DISABLE TRIGGER '+QUOTENAME(@nombre)+N' ON '+QUOTENAME(OBJECT_SCHEMA_NAME(@parent))+N'.'+QUOTENAME(OBJECT_NAME(@parent))+N';'; EXEC sys.sp_executesql @sql;
   FETCH NEXT FROM desactivartrg INTO @parent,@nombre;
  END;
  CLOSE desactivartrg; DEALLOCATE desactivartrg;
  INSERT dbo.VCT_PRM_AGENDA_ESTADOS(CODIGO,DESCRIPCION)
   SELECT c.CODIGO,c.DESCRIPCION FROM (VALUES('OC','Ocupado Certificacion'),('ND','No Disponible'),('D','Disponible'),('OP','Ocupado Personal'),('OA','Ocupado A'),('A','Agendado'),('LIC','Licencia'),('POT','Potencial')) c(CODIGO,DESCRIPCION)
   WHERE NOT EXISTS(SELECT 1 FROM dbo.VCT_PRM_AGENDA_ESTADOS e WHERE e.CODIGO COLLATE DATABASE_DEFAULT=c.CODIGO COLLATE DATABASE_DEFAULT);
  UPDATE d SET ID_ESTADO=e.ID FROM #D d JOIN dbo.VCT_PRM_AGENDA_ESTADOS e ON e.CODIGO COLLATE DATABASE_DEFAULT=UPPER(LTRIM(RTRIM(d.TIPO))) COLLATE DATABASE_DEFAULT;
  INSERT dbo.VCT_PRM_VIATICOS_TIPOS(CODIGO,DESCRIPCION,ORDEN,ESTADO,FECHA_ALTA,USUARIO_ALTA)
   SELECT c.CODIGO,c.DESCRIPCION,c.ORDEN,'ACTIVO',@ahora,'MIGRACION_LK' FROM (VALUES('MICRO','Micro',10),('HOTEL','Hotel',20),('REMIS','Remis',30),('AVION','Avion',40),('REFRIGERIO','Refrigerio',50),('TAXI','Taxi',60),('ALQUILER','Alquiler',70),('AUTO','Auto',80)) c(CODIGO,DESCRIPCION,ORDEN)
   WHERE NOT EXISTS(SELECT 1 FROM dbo.VCT_PRM_VIATICOS_TIPOS e WHERE e.CODIGO COLLATE DATABASE_DEFAULT=c.CODIGO COLLATE DATABASE_DEFAULT);
  UPDATE w SET ID_TIPO_VIATICO=e.ID FROM #W w JOIN dbo.VCT_PRM_VIATICOS_TIPOS e ON e.CODIGO COLLATE DATABASE_DEFAULT=UPPER(LTRIM(RTRIM(w.TIPO_PROVEEDOR))) COLLATE DATABASE_DEFAULT;
  DELETE dbo.VCT_PROYECTOS_VIATICOS_DET;
  DELETE dbo.VCT_PROYECTOS_VIATICOS;
  DELETE dbo.VCT_PROYECTOS_HONORARIOS;
  DELETE dbo.VCT_PROYECTOS_RENTABILIDAD;
  DELETE dbo.VCT_PROYECTOS_VISITAS_NORMAS;
  DELETE dbo.VCT_PROYECTOS_NORMAS;
  DELETE dbo.VCT_PROYECTOS_EQUIPO;
  DELETE dbo.VCT_PROYECTOS_VISITAS_CONSULTORES;
  DELETE dbo.VCT_AGENDA_PERSONAS;
  DELETE dbo.VCT_PROYECTOS_VISITAS;
  DELETE dbo.VCT_PROYECTOS_SERVICIOS;
  DELETE dbo.VCT_PROYECTOS;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS ON; SET @identity=N'VCT_PROYECTOS';
  INSERT dbo.VCT_PROYECTOS([CODIGO],[FECHA_INICIO_REAL],[FECHA_FIN_REAL],[MONTO_PRES],[MONTO_PRES_VIAT],[COSTO_MO],[COSTO_VIAT],[COSTO_VARIOS],[MONTO_TOTAL],[COSTO_TOTAL],[MONTO_COBRADO],[OBSERV_RENTA],[FECHA_PRESUPUESTO],[FECHA_ALTA],[USUARIO_ALTA],[TOTAL_HORAS_PROYECTADAS],[NIVEL_RIESGO],[ESTADO_COBRO],[ID],[IDCLIENTE],[NOMBRE],[REFERENCIA],[ID_ESTADO],[FECHA_INICIO],[FECHA_FIN],[PORCENTAJE_AVANCE],[MONEDA],[OBSERVACIONES],[IDPROPUESTA],[TOTAL_HORAS_EJECUTADAS],[IDCONTACTO]) SELECT [CODIGO],[FECHA_INICIO_REAL],[FECHA_FIN_REAL],[MONTO_PRES],[MONTO_PRES_VIAT],[COSTO_MO],[COSTO_VIAT],[COSTO_VARIOS],[MONTO_TOTAL],[COSTO_TOTAL],[MONTO_COBRADO],[OBSERV_RENTA],[FECHA_PRESUPUESTO],[FECHA_ALTA],[USUARIO_ALTA],[TOTAL_HORAS_PROYECTADAS],[NIVEL_RIESGO],[ESTADO_COBRO],[ID],[IDCLIENTE],[NOMBRE],[REFERENCIA],[ID_ESTADO],[FECHA_INICIO],[FECHA_FIN],[PORCENTAJE_AVANCE],[MONEDA],[OBSERVACIONES],[IDPROPUESTA],[TOTAL_HORAS_EJECUTADAS],[IDCONTACTO] FROM #P;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_SERVICIOS ON; SET @identity=N'VCT_PROYECTOS_SERVICIOS';
  INSERT dbo.VCT_PROYECTOS_SERVICIOS([ID_PROYECTO],[FECHA_INICIO],[FECHA_FIN],[FECHA_INICIO_REAL],[FECHA_FIN_REAL],[FECHA_ALTA],[USUARIO_ALTA],[LUGAR],[TOTAL_HORAS_PROYECTADAS],[ID],[ID_SERVICIO],[ID_ESTADO],[PRINCIPAL],[ORDEN],[SECUENCIA],[PORCENTAJE_AVANCE],[OBSERVACIONES],[NOMBRE],[TOTAL_HORAS_EJECUTADAS]) SELECT [ID_PROYECTO],[FECHA_INICIO],[FECHA_FIN],[FECHA_INICIO_REAL],[FECHA_FIN_REAL],[FECHA_ALTA],[USUARIO_ALTA],[LUGAR],[TOTAL_HORAS_PROYECTADAS],[ID],[ID_SERVICIO],[ID_ESTADO],[PRINCIPAL],[ORDEN],[SECUENCIA],[PORCENTAJE_AVANCE],[OBSERVACIONES],[NOMBRE],[TOTAL_HORAS_EJECUTADAS] FROM #S;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_SERVICIOS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS ON; SET @identity=N'VCT_PROYECTOS_VISITAS';
  INSERT dbo.VCT_PROYECTOS_VISITAS([ID_PROYECTO],[DIAS],[OBSERVADOR],[OBSERV_LOGISTICA],[OBSERV_CALIF],[INDICADOR_HR],[FECHA_ALTA],[USUARIO_ALTA],[ID],[ID_PROYECTO_SERVICIO],[FECHA_DESDE],[FECHA_HASTA],[LUGAR],[DESCRIPCION],[OBSERVACIONES],[ESTADO],[TOTAL_HORAS_EJECUTADAS],[HORAS_SIN_CONSULTOR]) SELECT [ID_PROYECTO],[DIAS],[OBSERVADOR],[OBSERV_LOGISTICA],[OBSERV_CALIF],[INDICADOR_HR],[FECHA_ALTA],[USUARIO_ALTA],[ID],[ID_PROYECTO_SERVICIO],[FECHA_DESDE],[FECHA_HASTA],[LUGAR],[DESCRIPCION],[OBSERVACIONES],[ESTADO],[TOTAL_HORAS_EJECUTADAS],[HORAS_SIN_CONSULTOR] FROM #V;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS_CONSULTORES ON; SET @identity=N'VCT_PROYECTOS_VISITAS_CONSULTORES';
  INSERT dbo.VCT_PROYECTOS_VISITAS_CONSULTORES([ID],[ID_VISITA],[ID_CONSULTOR],[LIDER],[HORAS_PLANIFICADAS],[HORAS_EJECUTADAS],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA]) SELECT [ID],[ID_VISITA],[ID_CONSULTOR],[LIDER],[HORAS_PLANIFICADAS],[HORAS_EJECUTADAS],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA] FROM #VC_ID;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS_CONSULTORES OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_EQUIPO ON; SET @identity=N'VCT_PROYECTOS_EQUIPO';
  INSERT dbo.VCT_PROYECTOS_EQUIPO([ID],[ID_PROYECTO],[ID_PROYECTO_SERVICIO],[TIPO_MIEMBRO],[ID_EMPLEADO],[ID_CONSULTOR],[ID_ROL],[PRINCIPAL],[FECHA_DESDE],[FECHA_HASTA],[ESTADO],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA]) SELECT [ID],[ID_PROYECTO],[ID_PROYECTO_SERVICIO],[TIPO_MIEMBRO],[ID_EMPLEADO],[ID_CONSULTOR],[ID_ROL],[PRINCIPAL],[FECHA_DESDE],[FECHA_HASTA],[ESTADO],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA] FROM #E;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_EQUIPO OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_NORMAS ON; SET @identity=N'VCT_PROYECTOS_NORMAS';
  INSERT dbo.VCT_PROYECTOS_NORMAS([ID],[ID_PROYECTO],[ID_PROYECTO_SERVICIO],[ID_NORMA],[PRINCIPAL],[OBLIGATORIA],[ESTADO],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA]) SELECT [ID],[ID_PROYECTO],[ID_PROYECTO_SERVICIO],[ID_NORMA],[PRINCIPAL],[OBLIGATORIA],[ESTADO],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA] FROM #PN;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_NORMAS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS_NORMAS ON; SET @identity=N'VCT_PROYECTOS_VISITAS_NORMAS';
  INSERT dbo.VCT_PROYECTOS_VISITAS_NORMAS([ID],[ID_VISITA],[ID_NORMA],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA]) SELECT [ID],[ID_VISITA],[ID_NORMA],[OBSERVACIONES],[FECHA_ALTA],[USUARIO_ALTA] FROM #VN;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VISITAS_NORMAS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_RENTABILIDAD ON; SET @identity=N'VCT_PROYECTOS_RENTABILIDAD';
  INSERT dbo.VCT_PROYECTOS_RENTABILIDAD([ID_PROYECTO_RENTA],[ID_PROYECTO],[PERIODO],[VENTAS],[COMPRAS],[FECHA_ALTA],[USUARIO_ALTA],[OBSERVACIONES]) SELECT [ID_PROYECTO_RENTA],[ID_PROYECTO],[PERIODO],[VENTAS],[COMPRAS],[FECHA_ALTA],[USUARIO_ALTA],[OBSERVACIONES] FROM #R;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_RENTABILIDAD OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_AGENDA_PERSONAS ON; SET @identity=N'VCT_AGENDA_PERSONAS';
  INSERT dbo.VCT_AGENDA_PERSONAS([FECHA],[DIA],[MES],[ANO],[ISHOLIDAY],[HOLIDAYTEXT],[TIPO],[FECHA_ALTA],[USUARIO_ALTA],[HORAS],[DESCRIPCION],[HORAS_DISP],[ID],[TIPO_ENTIDAD],[ID_CONSULTOR],[ID_EMPLEADO],[ID_PERSONA_ORIGEN],[ID_VISITA],[ID_AGENDA_ORIGEN],[ID_ESTADO],[OBSERVACIONES]) SELECT [FECHA],[DIA],[MES],[ANO],[ISHOLIDAY],[HOLIDAYTEXT],[TIPO],[FECHA_ALTA],[USUARIO_ALTA],[HORAS],[DESCRIPCION],[HORAS_DISP],[ID],[TIPO_ENTIDAD],[ID_CONSULTOR],[ID_EMPLEADO],[ID_PERSONA_ORIGEN],[ID_VISITA],[ID_AGENDA_ORIGEN],[ID_ESTADO],[OBSERVACIONES] FROM #D;
  SET IDENTITY_INSERT dbo.VCT_AGENDA_PERSONAS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_HONORARIOS ON; SET @identity=N'VCT_PROYECTOS_HONORARIOS';
  INSERT dbo.VCT_PROYECTOS_HONORARIOS([ID_TIPO_SERVICIO],[ID_AGENDA],[FECHA],[LUGAR],[IMPORTE],[ID],[ID_PROYECTO_ORIGEN],[ID_CONSULTOR_ORIGEN],[ID_PROYECTO],[ID_VISITA],[ID_PROYECTO_SERVICIO],[ID_CONSULTOR],[OBSERVACIONES],[IMPORTE_NUMERICO]) SELECT [ID_TIPO_SERVICIO],[ID_AGENDA],[FECHA],[LUGAR],[IMPORTE],[ID],[ID_PROYECTO_ORIGEN],[ID_CONSULTOR_ORIGEN],[ID_PROYECTO],[ID_VISITA],[ID_PROYECTO_SERVICIO],[ID_CONSULTOR],[OBSERVACIONES],[IMPORTE_NUMERICO] FROM #F;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_HONORARIOS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VIATICOS ON; SET @identity=N'VCT_PROYECTOS_VIATICOS';
  INSERT dbo.VCT_PROYECTOS_VIATICOS([ID_TIPO_SERVICIO],[ID_AGENDA],[TIPO_CONSULTOR],[TIPO_PROVEEDOR],[NRO_FC],[CANT_PERSONAS],[DESCRIP_SERVICIO],[FECHA_FC],[PRECIO_FINAL],[FORMA_PAGO],[CANT_CUOTAS],[ESTADO_PAGO],[FECHA_ULT_PAGO],[PRECIO_CUOTA],[PROX_VENCIMIENTO],[SALDO_PEND],[DESTINO],[FECHA_DESDE_SERV],[FECHA_HASTA_SERV],[DESC_FORMA_PAGO],[ID],[ID_PROYECTO_ORIGEN],[ID_CONSULTOR_ORIGEN],[ID_PROYECTO],[ID_VISITA],[ID_PROYECTO_SERVICIO],[ID_CONSULTOR],[OBSERVACIONES],[ID_PROVEEDOR_ORIGEN],[ID_PROVEEDOR],[ID_TIPO_VIATICO]) SELECT [ID_TIPO_SERVICIO],[ID_AGENDA],[TIPO_CONSULTOR],[TIPO_PROVEEDOR],[NRO_FC],[CANT_PERSONAS],[DESCRIP_SERVICIO],[FECHA_FC],[PRECIO_FINAL],[FORMA_PAGO],[CANT_CUOTAS],[ESTADO_PAGO],[FECHA_ULT_PAGO],[PRECIO_CUOTA],[PROX_VENCIMIENTO],[SALDO_PEND],[DESTINO],[FECHA_DESDE_SERV],[FECHA_HASTA_SERV],[DESC_FORMA_PAGO],[ID],[ID_PROYECTO_ORIGEN],[ID_CONSULTOR_ORIGEN],[ID_PROYECTO],[ID_VISITA],[ID_PROYECTO_SERVICIO],[ID_CONSULTOR],[OBSERVACIONES],[ID_PROVEEDOR_ORIGEN],[ID_PROVEEDOR],[ID_TIPO_VIATICO] FROM #W;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VIATICOS OFF; SET @identity=NULL;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VIATICOS_DET ON; SET @identity=N'VCT_PROYECTOS_VIATICOS_DET';
  INSERT dbo.VCT_PROYECTOS_VIATICOS_DET([ID_AGENDA],[DET_PROV_RESERVA],[DET_PROV_VUELO],[DET_PROV_ORIGEN],[DET_PROV_DESTINO],[DET_PROV_SALIDA],[DET_PROV_LLEGADA],[DET_PROV_LOCAL],[PAGA_CONSULTOR],[PAGA_CONSULTORA],[RENDICION_CLIENTE],[DET_PROV_KMS],[DET_PROV_PEAJES],[DET_PROV_FECHA],[DET_PROV_FINGRESO],[DET_PROV_FEGRESO],[DET_PROV_FPARTIDA],[DET_PROV_FLLEGADA],[ID],[ID_VIATICO],[ID_VISITA],[ID_PROYECTO_VIATICOS_ORIGEN],[KMS_NUMERICO],[PEAJES_NUMERICO],[OBSERVACIONES]) SELECT [ID_AGENDA],[DET_PROV_RESERVA],[DET_PROV_VUELO],[DET_PROV_ORIGEN],[DET_PROV_DESTINO],[DET_PROV_SALIDA],[DET_PROV_LLEGADA],[DET_PROV_LOCAL],[PAGA_CONSULTOR],[PAGA_CONSULTORA],[RENDICION_CLIENTE],[DET_PROV_KMS],[DET_PROV_PEAJES],[DET_PROV_FECHA],[DET_PROV_FINGRESO],[DET_PROV_FEGRESO],[DET_PROV_FPARTIDA],[DET_PROV_FLLEGADA],[ID],[ID_VIATICO],[ID_VISITA],[ID_PROYECTO_VIATICOS_ORIGEN],[KMS_NUMERICO],[PEAJES_NUMERICO],[OBSERVACIONES] FROM #WD;
  SET IDENTITY_INSERT dbo.VCT_PROYECTOS_VIATICOS_DET OFF; SET @identity=NULL;
  DECLARE validar CURSOR LOCAL FAST_FORWARD FOR SELECT Tabla,Temp,Esperadas,ColumnaId FROM #Resumen;
  DECLARE @temp sysname;
  OPEN validar; FETCH NEXT FROM validar INTO @nombre,@temp,@esperado,@columna;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @sql=N'SELECT @N=COUNT_BIG(*) FROM dbo.'+QUOTENAME(@nombre)+N';';
   EXEC sys.sp_executesql @sql,N'@N bigint OUTPUT',@N=@n OUTPUT;
   IF @n<>@esperado THROW 55011,'Conteos incorrectos; se revierte todo.',1;
   SET @sql=N'SELECT @H=CASE WHEN EXISTS(SELECT '+QUOTENAME(@columna)+N' FROM #'+@temp+N' EXCEPT SELECT '+QUOTENAME(@columna)+N' FROM dbo.'+QUOTENAME(@nombre)+N') OR EXISTS(SELECT '+QUOTENAME(@columna)+N' FROM dbo.'+QUOTENAME(@nombre)+N' EXCEPT SELECT '+QUOTENAME(@columna)+N' FROM #'+@temp+N') THEN 1 ELSE 0 END;';
   EXEC sys.sp_executesql @sql,N'@H bit OUTPUT',@H=@hay OUTPUT;
   IF @hay=1 THROW 55012,'IDs incorrectos; se revierte todo.',1;
   SET @tabla=N'dbo.'+QUOTENAME(@nombre);
   SET @sql=N'SELECT @M=MAX(CONVERT(bigint,'+QUOTENAME(@columna)+N')) FROM '+@tabla;
   EXEC sys.sp_executesql @sql,N'@M bigint OUTPUT',@M=@ultimo OUTPUT;
   SET @valor=CASE WHEN @ultimo IS NOT NULL THEN @ultimo WHEN EXISTS(SELECT 1 FROM sys.identity_columns WHERE object_id=OBJECT_ID(@tabla) AND last_value IS NULL) THEN 1 ELSE 0 END;
   SET @sql=N'DBCC CHECKIDENT(N'''+REPLACE(@tabla,'''','''''')+N''',RESEED,'+CONVERT(nvarchar(20),@valor)+N') WITH NO_INFOMSGS;'; EXEC sys.sp_executesql @sql;
   FETCH NEXT FROM validar INTO @nombre,@temp,@esperado,@columna;
  END;
  CLOSE validar; DEALLOCATE validar;
  DECLARE restaurar CURSOR LOCAL FAST_FORWARD FOR SELECT ParentId,Nombre,NoConfiable FROM #FKs WHERE Deshabilitada=0;
  OPEN restaurar; FETCH NEXT FROM restaurar INTO @parent,@nombre,@trust;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @tabla=QUOTENAME(OBJECT_SCHEMA_NAME(@parent))+N'.'+QUOTENAME(OBJECT_NAME(@parent));
   SET @sql=N'ALTER TABLE '+@tabla+N' WITH CHECK CHECK CONSTRAINT '+QUOTENAME(@nombre)+N';'; EXEC sys.sp_executesql @sql;
   IF @trust=1
   BEGIN
    SET @sql=N'ALTER TABLE '+@tabla+N' NOCHECK CONSTRAINT '+QUOTENAME(@nombre)+N'; ALTER TABLE '+@tabla+N' CHECK CONSTRAINT '+QUOTENAME(@nombre)+N';'; EXEC sys.sp_executesql @sql;
   END;
   FETCH NEXT FROM restaurar INTO @parent,@nombre,@trust;
  END;
  CLOSE restaurar; DEALLOCATE restaurar;
  DECLARE restaurartrg CURSOR LOCAL FAST_FORWARD FOR SELECT ParentId,Nombre FROM #Triggers;
  OPEN restaurartrg; FETCH NEXT FROM restaurartrg INTO @parent,@nombre;
  WHILE @@FETCH_STATUS=0
  BEGIN
   SET @sql=N'ENABLE TRIGGER '+QUOTENAME(@nombre)+N' ON '+QUOTENAME(OBJECT_SCHEMA_NAME(@parent))+N'.'+QUOTENAME(OBJECT_NAME(@parent)); EXEC sys.sp_executesql @sql;
   FETCH NEXT FROM restaurartrg INTO @parent,@nombre;
  END;
  CLOSE restaurartrg; DEALLOCATE restaurartrg;
  INSERT dbo.VCT_MIGRACION_PROYECTOS_EJECUCIONES(ID,FECHA,USUARIO,EXCEPCIONES) SELECT @run,@ahora,LEFT(SUSER_SNAME(),100),COUNT_BIG(*) FROM #Excepciones;
  INSERT dbo.VCT_MIGRACION_PROYECTOS_EXCEPCIONES(ID_EJECUCION,TABLA_ORIGEN,ID_ORIGEN,CAMPO,OBSERVACIONES) SELECT @run,TABLA_ORIGEN,ID_ORIGEN,CAMPO,OBSERVACIONES FROM #Excepciones;
  COMMIT TRANSACTION;
  SELECT N'MIGRACION PROYECTOS CONFIRMADA' Resultado,@run ID_EJECUCION;
  SELECT Tabla,Esperadas FilasCargadas FROM #Resumen ORDER BY Tabla;
 END TRY
 BEGIN CATCH
  IF XACT_STATE()<>0 ROLLBACK TRANSACTION;
  IF @identity IS NOT NULL
  BEGIN TRY
   SET @sql=N'SET IDENTITY_INSERT dbo.'+QUOTENAME(@identity)+N' OFF;'; EXEC sys.sp_executesql @sql;
  END TRY
  BEGIN CATCH
   PRINT N'Cerrar esta conexion antes de reintentar: no pudo limpiarse IDENTITY_INSERT.';
  END CATCH;
  THROW;
 END CATCH;
END;
